<#
.SYNOPSIS
GUI and packaged launcher for the Purview Teams PST to HTML converter.
.DESCRIPTION
This launcher embeds the converter script, writes it to a temporary file at runtime, and invokes it in STA mode.
It can run interactively with a WinForms UI or non-interactively for smoke tests and automation.
#>
[CmdletBinding()]
param(
    [string]$PstPath,
    [string]$OutputPath,
    [string]$LogPath,
    [string[]]$DefaultConversationParticipants = @(),
    [bool]$TeamsReport = $true,
    [bool]$EmailReport = $true,
    [bool]$CalendarReport = $true,
    [bool]$ContactsReport = $true,
    [switch]$KeepPstAttached,
    [switch]$UseSampleData,
    [switch]$NoGui
)

$legacyReportFlagBound = $PSBoundParameters.ContainsKey('TeamsReport') -or $PSBoundParameters.ContainsKey('EmailReport')
$newReportFlagBound = $PSBoundParameters.ContainsKey('CalendarReport') -or $PSBoundParameters.ContainsKey('ContactsReport')
if ($legacyReportFlagBound -and -not $newReportFlagBound) {
    # Preserve pre-Calendar/Contacts command lines while normal no-argument launches
    # retain the public all-four defaults.
    $CalendarReport = $false
    $ContactsReport = $false
}

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$script:EmbeddedCoreBase64 = ''

function Get-DefaultOutputDirectory {
    $downloads = Join-Path ([Environment]::GetFolderPath('UserProfile')) 'Downloads'
    if (Test-Path -LiteralPath $downloads) { return $downloads }
    return [Environment]::GetFolderPath('UserProfile')
}

function New-EmbeddedCoreScript {
    # Decode first so a corrupt/incomplete payload fails before any temp dir is created (no leak).
    try { $coreBytes = [Convert]::FromBase64String($script:EmbeddedCoreBase64) }
    catch { throw 'The packaged converter is corrupted or incomplete. Please reinstall the application.' }
    $tempRoot = Join-Path ([IO.Path]::GetTempPath()) ('PurviewTeamsPstToHtml_' + [guid]::NewGuid().ToString('N'))
    [System.IO.Directory]::CreateDirectory($tempRoot) | Out-Null
    $corePath = Join-Path $tempRoot 'Convert-PurviewTeamsPstToHtml.ps1'
    [IO.File]::WriteAllBytes($corePath, $coreBytes)
    # Read the file back and confirm it matches what we decoded (guards against on-disk
    # tampering or a partial write between here and launch). Mismatch => clean up, no leak.
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $expectedHash = [BitConverter]::ToString($sha.ComputeHash($coreBytes))
        $actualHash = [BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($corePath)))
    }
    finally { $sha.Dispose() }
    if ($expectedHash -ne $actualHash) {
        Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
        throw 'The packaged converter failed an integrity check. Please reinstall the application.'
    }
    return $corePath
}

function ConvertTo-ArgumentList {
    param(
        [string]$CorePath,
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants,
        [bool]$TeamsReport,
        [bool]$EmailReport,
        [bool]$CalendarReport,
        [bool]$ContactsReport,
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [string]$RunId
    )

    $args = [System.Collections.Generic.List[string]]::new()
    $args.Add('-Sta')
    $args.Add('-NoProfile')
    $args.Add('-ExecutionPolicy')
    $args.Add('Bypass')
    $args.Add('-File')
    $args.Add($CorePath)
    $args.Add('-NoPrompt')

    if ($UseSampleData) { $args.Add('-UseSampleData') }
    elseif (-not [string]::IsNullOrWhiteSpace($PstPath)) { $args.Add('-PstPath'); $args.Add($PstPath) }

    if (-not [string]::IsNullOrWhiteSpace($OutputPath)) { $args.Add('-OutputPath'); $args.Add($OutputPath) }
    if (-not [string]::IsNullOrWhiteSpace($LogPath)) { $args.Add('-LogPath'); $args.Add($LogPath) }
    $args.Add(('-TeamsReport:' + $(if ($TeamsReport) { '$true' } else { '$false' })))
    $args.Add(('-EmailReport:' + $(if ($EmailReport) { '$true' } else { '$false' })))
    $args.Add(('-CalendarReport:' + $(if ($CalendarReport) { '$true' } else { '$false' })))
    $args.Add(('-ContactsReport:' + $(if ($ContactsReport) { '$true' } else { '$false' })))
    if ($KeepPstAttached) { $args.Add('-KeepPstAttached') }
    if (-not [string]::IsNullOrWhiteSpace($RunId)) { $args.Add('-RunId'); $args.Add($RunId) }
    foreach ($participant in @($DefaultConversationParticipants)) {
        if (-not [string]::IsNullOrWhiteSpace($participant)) {
            $args.Add('-DefaultConversationParticipants')
            $args.Add($participant.Trim())
        }
    }
    return $args.ToArray()
}

function ConvertTo-NativeArgumentString {
    param([string[]]$Argument)
    $quoted = foreach ($arg in @($Argument)) {
        if ($null -eq $arg) { '""'; continue }
        if ($arg -notmatch '[\s"]') { $arg; continue }
        '"' + ($arg -replace '([\\]*)"', '$1$1\"' -replace '([\\]+)$', '$1$1') + '"'
    }
    return ($quoted -join ' ')
}

# ponytail: keep in sync with ReportPathNaming.ps1
function Get-ReportPathBaseName {
    param([Parameter(Mandatory = $true)][string]$FilePath)
    $name = [IO.Path]::GetFileNameWithoutExtension($FilePath)
    if ($name -match '(?i)_Teams$') { $name = $name.Substring(0, $name.Length - 6) }
    elseif ($name -match '(?i)_Email$') { $name = $name.Substring(0, $name.Length - 6) }
    elseif ($name -match '(?i)_Calendar$') { $name = $name.Substring(0, $name.Length - 9) }
    elseif ($name -match '(?i)_Contacts$') { $name = $name.Substring(0, $name.Length - 9) }
    elseif ($name -match '(?i)_Dashboard$') { $name = $name.Substring(0, $name.Length - 10) }
    return $name
}

function Get-ReportOutputPaths {
    param(
        [Parameter(Mandatory = $true)][string]$DisplayPath,
        [Parameter(Mandatory = $true)][bool]$TeamsReport,
        [Parameter(Mandatory = $true)][bool]$EmailReport,
        [bool]$CalendarReport = $false,
        [bool]$ContactsReport = $false
    )
    if (-not $TeamsReport -and -not $EmailReport -and -not $CalendarReport -and -not $ContactsReport) {
        throw 'At least one report type must be selected.'
    }
    $dir = [IO.Path]::GetDirectoryName($DisplayPath)
    if ([string]::IsNullOrWhiteSpace($dir)) { $dir = (Get-Location).Path }
    $inputExt = [IO.Path]::GetExtension($DisplayPath)
    $isLogPath = $inputExt -in @('.log', '.txt')
    $teamsExt = if ($isLogPath) { $inputExt } else { '.db' }
    $emailExt = if ($isLogPath) { $inputExt } else { '.db' }
    $calendarExt = if ($isLogPath) { $inputExt } else { '.html' }
    $contactsExt = if ($isLogPath) { $inputExt } else { '.html' }
    $displayExt = if ($isLogPath) { $inputExt } else { '.html' }
    $base = Get-ReportPathBaseName -FilePath $DisplayPath
    $teamsPath = if ($TeamsReport) { Join-Path $dir ($base + '_Teams' + $teamsExt) } else { $null }
    $emailPath = if ($EmailReport) { Join-Path $dir ($base + '_Email' + $emailExt) } else { $null }
    $calendarPath = if ($CalendarReport) { Join-Path $dir ($base + '_Calendar' + $calendarExt) } else { $null }
    $contactsPath = if ($ContactsReport) { Join-Path $dir ($base + '_Contacts' + $contactsExt) } else { $null }
    $selectedPaths = @(@($teamsPath, $emailPath, $calendarPath, $contactsPath) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $display = if (@($selectedPaths).Count -eq 1) { $selectedPaths[0] } else { Join-Path $dir ($base + $displayExt) }
    [pscustomobject]@{
        DisplayPath = $display
        TeamsPath = $teamsPath
        EmailPath = $emailPath
        CalendarPath = $calendarPath
        ContactsPath = $contactsPath
    }
}

# ponytail: keep in sync with ReportPathNaming.ps1
function Get-DashboardOutputPath {
    param([Parameter(Mandatory = $true)][string]$DisplayPath)
    $dir = [IO.Path]::GetDirectoryName($DisplayPath)
    if ([string]::IsNullOrWhiteSpace($dir)) { $dir = (Get-Location).Path }
    return (Join-Path $dir ((Get-ReportPathBaseName -FilePath $DisplayPath) + '_Dashboard.html'))
}

# ponytail: keep in sync with ReportPathNaming.ps1
function Get-SafePstFolderName {
    param([Parameter(Mandatory = $true)][string]$PstPath)
    $name = [IO.Path]::GetFileNameWithoutExtension($PstPath)
    if ([string]::IsNullOrWhiteSpace($name)) { return 'PurviewPstReport' }
    foreach ($char in [IO.Path]::GetInvalidFileNameChars()) {
        $name = $name.Replace([string]$char, '_')
    }
    $name = $name.Trim()
    if ([string]::IsNullOrWhiteSpace($name)) { return 'PurviewPstReport' }
    return $name
}

# ponytail: keep in sync with ReportPathNaming.ps1
function Resolve-PathInPstDownloadsFolder {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(Mandatory = $true)][string]$PstPath,
        [Parameter(Mandatory = $true)][string]$DownloadsDirectory
    )
    $dir = [IO.Path]::GetDirectoryName($FilePath)
    if ([string]::IsNullOrWhiteSpace($dir)) { $dir = $DownloadsDirectory }
    try {
        $dirFull = [IO.Path]::GetFullPath($dir).TrimEnd('\')
        $downloadsFull = [IO.Path]::GetFullPath($DownloadsDirectory).TrimEnd('\')
    }
    catch {
        return $FilePath
    }
    if ($dirFull -ine $downloadsFull) { return $FilePath }
    $fileName = [IO.Path]::GetFileName($FilePath)
    if ([string]::IsNullOrWhiteSpace($fileName)) { return $FilePath }
    return (Join-Path (Join-Path $DownloadsDirectory (Get-SafePstFolderName -PstPath $PstPath)) $fileName)
}

function Get-DashboardLaunchPath {
    # The core reports the dashboard it wrote; deriving from the output box is only a fallback
    # for result lines produced before DashboardOutputPath existed.
    param(
        [AllowNull()][hashtable]$Fields,
        [Parameter(Mandatory = $true)][string]$DisplayPath
    )
    if ($null -ne $Fields -and $Fields.ContainsKey('DashboardOutputPath')) {
        $reported = [string]$Fields['DashboardOutputPath']
        if (-not [string]::IsNullOrWhiteSpace($reported)) { return $reported }
    }
    return (Get-DashboardOutputPath -DisplayPath $DisplayPath)
}

function Resolve-PowerShell7Path {
    $cmd = Get-Command pwsh -ErrorAction SilentlyContinue
    $candidateProperties = @('Source','Path','Definition')
    foreach ($property in $candidateProperties) {
        if ($cmd -and ($cmd.PSObject.Properties.Name -contains $property)) {
            $candidate = [string]$cmd.$property
            if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                return $candidate
            }
        }
    }

    $standardPaths = @(
        (Join-Path $env:ProgramFiles 'PowerShell\7\pwsh.exe'),
        (Join-Path ${env:ProgramFiles(x86)} 'PowerShell\7\pwsh.exe')
    )
    foreach ($candidate in $standardPaths) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            return $candidate
        }
    }

    throw 'PowerShell 7 is required for this converter, but it was not found on this computer. Install PowerShell 7 from Microsoft, then run the converter again.'
}

function Get-CurrentExecutablePath {
    try {
        $processPathProperty = [Environment].GetProperty('ProcessPath')
        if ($processPathProperty) {
            $path = [string]$processPathProperty.GetValue($null)
            if (-not [string]::IsNullOrWhiteSpace($path)) { return $path }
        }
    }
    catch { }
    try {
        return [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    }
    catch {
        return ''
    }
}

function Resolve-EmailViewerPath {
    param(
        [AllowEmptyString()][string]$ProcessPath = (Get-CurrentExecutablePath),
        [AllowEmptyString()][string]$ScriptDirectory = $PSScriptRoot,
        [AllowEmptyString()][string]$AppBaseDirectory = ([AppContext]::BaseDirectory)
    )
    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($env:PURVIEW_EMAIL_VIEWER_PATH)) {
        $candidates.Add($env:PURVIEW_EMAIL_VIEWER_PATH)
    }
    if (-not [string]::IsNullOrWhiteSpace($ProcessPath)) {
        $processDirectory = [IO.Path]::GetDirectoryName($ProcessPath)
        if (-not [string]::IsNullOrWhiteSpace($processDirectory)) {
            $candidates.Add((Join-Path $processDirectory 'EmailReviewViewer\EmailReviewViewer.App.exe'))
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($ScriptDirectory)) {
        $candidates.Add((Join-Path $ScriptDirectory 'EmailReviewViewer\EmailReviewViewer.App.exe'))
        $candidates.Add((Join-Path $ScriptDirectory '..\EmailReviewViewer\EmailReviewViewer.App\bin\Release\net8.0-windows\EmailReviewViewer.App.exe'))
        $candidates.Add((Join-Path $ScriptDirectory '..\EmailReviewViewer\artifacts\publish\win-x64\EmailReviewViewer.App.exe'))
    }
    if (-not [string]::IsNullOrWhiteSpace($AppBaseDirectory)) {
        $candidates.Add((Join-Path $AppBaseDirectory 'EmailReviewViewer\EmailReviewViewer.App.exe'))
    }
    foreach ($candidate in $candidates) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and
            (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            return [IO.Path]::GetFullPath($candidate)
        }
    }
    throw "Email report requires EmailReviewViewer\EmailReviewViewer.App.exe. Searched: $($candidates -join '; ')"
}

function Invoke-EmbeddedConversion {
    param(
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants = @(),
        [bool]$TeamsReport = $true,
        [bool]$EmailReport = $true,
        [bool]$CalendarReport = $true,
        [bool]$ContactsReport = $true,
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [scriptblock]$OnProgress
    )

    $corePath = New-EmbeddedCoreScript
    try {
        $pwsh = Resolve-PowerShell7Path

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $pwsh
        $childArgs = ConvertTo-ArgumentList -CorePath $corePath -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -TeamsReport:$TeamsReport -EmailReport:$EmailReport -CalendarReport:$CalendarReport -ContactsReport:$ContactsReport -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData
        $psi.Arguments = ConvertTo-NativeArgumentString -Argument $childArgs
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        if ($EmailReport -or $TeamsReport) {
            $viewerPath = Resolve-EmailViewerPath
            $psi.EnvironmentVariables['PURVIEW_EMAIL_VIEWER_PATH'] = $viewerPath
            $psi.EnvironmentVariables['PURVIEW_TEAMS_VIEWER_PATH'] = $viewerPath
        }

        $stdoutBuilder = [System.Text.StringBuilder]::new()
        $proc = [System.Diagnostics.Process]::Start($psi)
        # Drain stderr concurrently so a full stderr pipe buffer can't deadlock the
        # synchronous stdout read below. ReadToEndAsync (StreamReader, .NET 4.5+) runs
        # the stderr read on the thread pool without a PowerShell event handler.
        $stderrTask = $proc.StandardError.ReadToEndAsync()
        while (-not $proc.StandardOutput.EndOfStream) {
            $line = $proc.StandardOutput.ReadLine()
            [void]$stdoutBuilder.AppendLine($line)
            if ($line -like 'CONVERSION_PROGRESS|*' -and $OnProgress) {
                & $OnProgress $line
            }
        }
        $stderr = $stderrTask.Result
        $proc.WaitForExit()
        $stdout = $stdoutBuilder.ToString()

        [pscustomobject]@{
            ExitCode = $proc.ExitCode
            StdOut = $stdout
            StdErr = $stderr
            ResultLine = (($stdout -split "`r?`n") | Where-Object { $_ -like 'CONVERSION_RESULT|*' } | Select-Object -Last 1)
            ErrorLine = (($stdout -split "`r?`n") | Where-Object { $_ -like 'CONVERSION_ERROR|*' } | Select-Object -Last 1)
        }
    }
    finally {
        if ($corePath -and (Test-Path -LiteralPath $corePath)) {
            $tempDir = Split-Path -Path $corePath -Parent
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}
# --- Child process lifetime: Win32 Job Object + tree kill -------------------------------
# The launcher holds ONE kill-on-close Job Object for its whole lifetime. The child pwsh is
# assigned to it, so if the launcher process is hard-killed the OS closes the handle and reaps
# the child (and any descendants it spawned). Explicit stop still uses taskkill /T for an
# immediate tree kill; the two mechanisms are complementary.
$script:JobObjectSource = @'
using System;
using System.Runtime.InteropServices;

public static class PurviewJobNative
{
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr CreateJobObject(IntPtr lpJobAttributes, string lpName);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool SetInformationJobObject(IntPtr hJob, int JobObjectInfoClass, IntPtr lpJobObjectInfo, uint cbJobObjectInfoLength);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool AssignProcessToJobObject(IntPtr hJob, IntPtr hProcess);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool CloseHandle(IntPtr hObject);

    [StructLayout(LayoutKind.Sequential)]
    public struct JOBOBJECT_BASIC_LIMIT_INFORMATION
    {
        public long PerProcessUserTimeLimit;
        public long PerJobUserTimeLimit;
        public uint LimitFlags;
        public UIntPtr MinimumWorkingSetSize;
        public UIntPtr MaximumWorkingSetSize;
        public uint ActiveProcessLimit;
        public UIntPtr Affinity;
        public uint PriorityClass;
        public uint SchedulingClass;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct IO_COUNTERS
    {
        public ulong ReadOperationCount;
        public ulong WriteOperationCount;
        public ulong OtherOperationCount;
        public ulong ReadTransferCount;
        public ulong WriteTransferCount;
        public ulong OtherTransferCount;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION
    {
        public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
        public IO_COUNTERS IoInfo;
        public UIntPtr ProcessMemoryLimit;
        public UIntPtr JobMemoryLimit;
        public UIntPtr PeakProcessMemoryUsed;
        public UIntPtr PeakJobMemoryUsed;
    }

    public const int JobObjectExtendedLimitInformation = 9;
    public const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x2000;

    // Marshaling JOBOBJECT_EXTENDED_LIMIT_INFORMATION by hand from PowerShell 5.1 is
    // error-prone, so create + configure the kill-on-close job here and hand back the handle.
    public static IntPtr CreateKillOnCloseJob()
    {
        IntPtr hJob = CreateJobObject(IntPtr.Zero, null);
        if (hJob == IntPtr.Zero) { return IntPtr.Zero; }

        JOBOBJECT_EXTENDED_LIMIT_INFORMATION info = new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
        info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;

        int length = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
        IntPtr ptr = Marshal.AllocHGlobal(length);
        try
        {
            Marshal.StructureToPtr(info, ptr, false);
            if (!SetInformationJobObject(hJob, JobObjectExtendedLimitInformation, ptr, (uint)length))
            {
                CloseHandle(hJob);
                return IntPtr.Zero;
            }
        }
        finally
        {
            Marshal.FreeHGlobal(ptr);
        }
        return hJob;
    }
}
'@

$script:launcherJobHandle = [IntPtr]::Zero
$script:launcherJobUnavailable = $false

function Initialize-LauncherJobObject {
    # Lazily creates the one launcher-lifetime kill-on-close Job Object. Returns its handle,
    # or [IntPtr]::Zero if the type/handle could not be created. The handle is intentionally
    # never closed - the OS closes it when the launcher exits, which is what reaps the child.
    if ($script:launcherJobHandle -ne [IntPtr]::Zero) { return $script:launcherJobHandle }
    if ($script:launcherJobUnavailable) { return [IntPtr]::Zero }
    try {
        if (-not ([System.Management.Automation.PSTypeName]'PurviewJobNative').Type) {
            Add-Type -TypeDefinition $script:JobObjectSource -Language CSharp
        }
        $handle = [PurviewJobNative]::CreateKillOnCloseJob()
        if ($handle -eq [IntPtr]::Zero) { $script:launcherJobUnavailable = $true; return [IntPtr]::Zero }
        $script:launcherJobHandle = $handle
        return $handle
    }
    catch {
        $script:launcherJobUnavailable = $true
        return [IntPtr]::Zero
    }
}

function Add-ProcessToLauncherJob {
    # Assigns a running process to the launcher job. A failure here must NOT abort the
    # conversion - explicit stop still relies on Stop-ProcessTree.
    param([Parameter(Mandatory = $true)][System.Diagnostics.Process]$Process)
    try {
        $handle = Initialize-LauncherJobObject
        if ($handle -eq [IntPtr]::Zero) { return $false }
        return [PurviewJobNative]::AssignProcessToJobObject($handle, $Process.Handle)
    }
    catch { return $false }
}

function Stop-ProcessTree {
    # Terminates a child process AND its descendants. .NET Framework's Process.Kill() has no
    # tree overload, so grandchildren (a pwsh that spawned more, Outlook COM helpers) would be
    # orphaned. taskkill /T /F kills the whole tree; fall back to Kill() if taskkill can't run.
    # Never throws - safe to call from teardown/FormClosing paths.
    param([AllowNull()][System.Diagnostics.Process]$Process)
    if ($null -eq $Process) { return }
    $procId = -1
    try {
        if ($Process.HasExited) { return }
        $procId = $Process.Id
    }
    catch { return }
    if ($procId -le 0) { return }

    $treeKilled = $false
    try {
        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = 'taskkill.exe'
        $psi.Arguments = "/PID $procId /T /F"
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $killer = [System.Diagnostics.Process]::Start($psi)
        if ($null -ne $killer) {
            [void]$killer.WaitForExit(5000)
            if ($killer.HasExited -and $killer.ExitCode -eq 0) {
                $treeKilled = $true
            }
        }
    }
    catch { $treeKilled = $false }

    if (-not $treeKilled) {
        try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
    }
}

function Start-EmbeddedConversionProcess {
    param(
        [string]$PstPath,
        [string]$OutputPath,
        [string]$LogPath,
        [string[]]$DefaultConversationParticipants = @(),
        [bool]$TeamsReport = $true,
        [bool]$EmailReport = $true,
        [bool]$CalendarReport = $true,
        [bool]$ContactsReport = $true,
        [switch]$KeepPstAttached,
        [switch]$UseSampleData,
        [string]$RunId
    )

    $corePath = New-EmbeddedCoreScript
    $proc = $null
    $subscription = $null
    try {
        $pwsh = Resolve-PowerShell7Path

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $pwsh
        $childArgs = ConvertTo-ArgumentList -CorePath $corePath -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -TeamsReport:$TeamsReport -EmailReport:$EmailReport -CalendarReport:$CalendarReport -ContactsReport:$ContactsReport -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData -RunId $RunId
        $psi.Arguments = ConvertTo-NativeArgumentString -Argument $childArgs
        $psi.UseShellExecute = $false
        # Redirect stdout so the run-ID-tagged progress/stage lines can drive the GUI.
        # Stderr stays un-redirected; fatal-error detail is still read from the log file.
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $false
        $psi.CreateNoWindow = $true
        if ($EmailReport -or $TeamsReport) {
            $viewerPath = Resolve-EmailViewerPath
            $psi.EnvironmentVariables['PURVIEW_EMAIL_VIEWER_PATH'] = $viewerPath
            $psi.EnvironmentVariables['PURVIEW_TEAMS_VIEWER_PATH'] = $viewerPath
        }

        # Thread-safe hand-off: the OutputDataReceived handler runs on a non-UI thread and
        # MUST NOT touch WinForms controls; it only enqueues raw stdout lines. The WinForms
        # timer drains this queue on the UI thread. Verified in PS 5.1 that a
        # Register-ObjectEvent -Action enqueue fires during a modal ShowDialog loop, whereas a
        # raw add_OutputDataReceived scriptblock delegate crashes the process.
        $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
        $proc = [System.Diagnostics.Process]::new()
        $proc.StartInfo = $psi
        $subscription = Register-ObjectEvent -InputObject $proc -EventName OutputDataReceived -MessageData $queue -Action {
            if ($null -ne $EventArgs.Data) { $Event.MessageData.Enqueue($EventArgs.Data) }
        }
        [void]$proc.Start()
        # Bind the child to the launcher job before it spawns descendants so KILL_ON_JOB_CLOSE
        # reaps the whole tree if the launcher dies. Best-effort: never abort the conversion.
        [void](Add-ProcessToLauncherJob -Process $proc)
        $proc.BeginOutputReadLine()

        [pscustomobject]@{
            Process = $proc
            CorePath = $corePath
            TempDir = Split-Path -Path $corePath -Parent
            OutputQueue = $queue
            OutputSubscription = $subscription
        }
    }
    catch {
        # If Start()/BeginOutputReadLine() (or anything after the subscription) threw, the
        # event subscription and process are already live - tear them down so repeated failed
        # clicks can't accumulate orphaned subscribers.
        if ($subscription) {
            Stop-ConversionOutputReader -Conversion ([pscustomobject]@{ Process = $proc; OutputSubscription = $subscription })
        }
        if ($proc) { try { $proc.Dispose() } catch { } }
        if ($corePath -and (Test-Path -LiteralPath $corePath)) {
            $tempDir = Split-Path -Path $corePath -Parent
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
        throw
    }
}


function ConvertFrom-ProgressStdoutLine {
    # Pure, side-effect-free mapper from a core stdout line to a GUI progress step.
    # Returns $null for anything that is NOT an applicable current-run progress/stage line:
    #   - not a CONVERSION_PROGRESS / CONVERSION_STAGE machine line
    #   - a line whose RunId != ExpectedRunId (foreign run)
    #   - a line with no RunId while an ExpectedRunId is set (stale/pre-RunId line)
    #   - a malformed line (never throws)
    # Otherwise returns [pscustomobject]@{ Percent = <int>; Status = <string> }.
    # Percent bands mirror the timer's historical mapping: collected 15-58,
    # FinishedReading 60, PreparingReport 62, WritingReport 66 (start) / 68-91 (progress),
    # Finalizing 92, Detaching 94, ReportWritten 96.
    param(
        [AllowNull()][string]$Line,
        [AllowNull()][string]$ExpectedRunId
    )

    if ([string]::IsNullOrWhiteSpace($Line)) { return $null }
    # No active run id means nothing is applicable; also stops an untagged line from matching
    # an empty expected id on control reuse.
    if ([string]::IsNullOrEmpty($ExpectedRunId)) { return $null }
    if ($Line -notmatch '^CONVERSION_(PROGRESS|STAGE)\|') { return $null }

    $fields = @{}
    foreach ($part in ($Line -split '\|')) {
        $idx = $part.IndexOf('=')
        if ($idx -gt 0) { $fields[$part.Substring(0, $idx)] = $part.Substring($idx + 1) }
    }

    # RunId gating: only current-run lines are applicable. A missing RunId yields ''
    # which will not equal a non-empty ExpectedRunId, so stale/foreign lines are ignored.
    $lineRunId = if ($fields.ContainsKey('RunId')) { [string]$fields['RunId'] } else { '' }
    if ($lineRunId -ne [string]$ExpectedRunId) { return $null }

    if ($Line -match '^CONVERSION_PROGRESS\|') {
        $collected = 0
        if ($fields.ContainsKey('ItemsExported')) { [void][int]::TryParse([string]$fields['ItemsExported'], [ref]$collected) }
        $percent = [Math]::Min(58, 15 + [int][Math]::Ceiling($collected / 400))
        $status = "Reading PST... collected $collected"
        if ($fields.ContainsKey('FolderPath') -and -not [string]::IsNullOrWhiteSpace([string]$fields['FolderPath'])) {
            $status += "; folder: $([string]$fields['FolderPath'])"
        }
        return [pscustomobject]@{ Percent = $percent; Status = $status }
    }

    # CONVERSION_STAGE
    $stage = if ($fields.ContainsKey('Stage')) { [string]$fields['Stage'] } else { '' }
    switch ($stage) {
        'FinishedReading' { return [pscustomobject]@{ Percent = 60; Status = 'Finished reading PST. Preparing report...' } }
        'PreparingReport' { return [pscustomobject]@{ Percent = 62; Status = 'Preparing HTML report...' } }
        'WritingReport' {
            $written = 0; $total = 0
            if ($fields.ContainsKey('Written')) { [void][int]::TryParse([string]$fields['Written'], [ref]$written) }
            if ($fields.ContainsKey('Total')) { [void][int]::TryParse([string]$fields['Total'], [ref]$total) }
            if ($written -le 0) {
                return [pscustomobject]@{ Percent = 66; Status = 'Writing HTML report...' }
            }
            $total = [Math]::Max(1, $total)
            $percent = [Math]::Min(91, 68 + [int][Math]::Floor(($written / $total) * 23))
            return [pscustomobject]@{ Percent = $percent; Status = "Writing HTML report... $written of $total conversations" }
        }
        'Finalizing'   { return [pscustomobject]@{ Percent = 92; Status = 'Finalizing HTML report...' } }
        'ImportingTeamsDatabase' { return [pscustomobject]@{ Percent = 93; Status = 'Importing Teams database...' } }
        'ImportingEmailDatabase' { return [pscustomobject]@{ Percent = 93; Status = 'Importing Email database...' } }
        'Detaching'    { return [pscustomobject]@{ Percent = 94; Status = 'Detaching PST and cleaning up...' } }
        'ReportWritten' { return [pscustomobject]@{ Percent = 96; Status = 'Cleaning up...' } }
        default { return $null }
    }
}

function Stop-ConversionOutputReader {
    # Tears down the async stdout reader and its event subscription so no handler leaks
    # after a conversion completes or the window closes. Safe to call more than once.
    param([AllowNull()][object]$Conversion)
    if ($null -eq $Conversion) { return }
    try { if ($Conversion.Process) { $Conversion.Process.CancelOutputRead() } } catch { }
    if ($Conversion.PSObject.Properties.Name -contains 'OutputSubscription' -and $Conversion.OutputSubscription) {
        try { Unregister-Event -SourceIdentifier $Conversion.OutputSubscription.Name -ErrorAction SilentlyContinue } catch { }
        try { Remove-Job -Id $Conversion.OutputSubscription.Id -Force -ErrorAction SilentlyContinue } catch { }
    }
}

function Split-PipeDelimitedStdoutLine {
    param([AllowNull()][string]$Line)
    $fields = @{}
    if ([string]::IsNullOrWhiteSpace($Line)) { return $fields }
    foreach ($part in ($Line -split '\|')) {
        $idx = $part.IndexOf('=')
        if ($idx -gt 0) { $fields[$part.Substring(0, $idx)] = $part.Substring($idx + 1) }
    }
    return $fields
}

function ConvertFrom-ResultLine {
    param([AllowNull()][string]$ResultLine)
    $result = @{}
    if ([string]::IsNullOrWhiteSpace($ResultLine)) { return $result }
    $fields = Split-PipeDelimitedStdoutLine -Line $ResultLine
    foreach ($key in $fields.Keys) {
        if ($key -ne 'CONVERSION_RESULT' -and $key -ne 'CONVERSION_ERROR') { $result[$key] = $fields[$key] }
    }
    return $result
}

# ponytail: keep in sync with ReportPathNaming.ps1 Get-WritePathsFromResultFields
function Get-WritePathsFromResultFields {
    # Prefer typed report write targets. Never treat a multi-report DisplayPath (OutputPath /
    # LogPath when multiple reports are selected and typed paths exist) as a required file.
    param([AllowNull()][hashtable]$Fields)
    if ($null -eq $Fields) { $Fields = @{} }
    $reportPaths = [System.Collections.Generic.List[string]]::new()
    $hasTypedReport = $false
    foreach ($key in @('TeamsOutputPath', 'EmailOutputPath', 'CalendarOutputPath', 'ContactsOutputPath')) {
        if ($Fields.ContainsKey($key)) {
            $path = [string]$Fields[$key]
            if (-not [string]::IsNullOrWhiteSpace($path)) {
                $hasTypedReport = $true
                if (-not $reportPaths.Contains($path)) { [void]$reportPaths.Add($path) }
            }
        }
    }
    if (-not $hasTypedReport -and $Fields.ContainsKey('OutputPath')) {
        $path = [string]$Fields['OutputPath']
        if (-not [string]::IsNullOrWhiteSpace($path)) { [void]$reportPaths.Add($path) }
    }
    $logPaths = [System.Collections.Generic.List[string]]::new()
    $hasTypedLog = $false
    foreach ($key in @('TeamsLogPath', 'EmailLogPath', 'CalendarLogPath', 'ContactsLogPath')) {
        if ($Fields.ContainsKey($key)) {
            $path = [string]$Fields[$key]
            if (-not [string]::IsNullOrWhiteSpace($path)) {
                $hasTypedLog = $true
                if (-not $logPaths.Contains($path)) { [void]$logPaths.Add($path) }
            }
        }
    }
    if (-not $hasTypedLog -and $Fields.ContainsKey('LogPath')) {
        $path = [string]$Fields['LogPath']
        if (-not [string]::IsNullOrWhiteSpace($path)) { [void]$logPaths.Add($path) }
    }
    [pscustomobject]@{
        ReportPaths = $reportPaths.ToArray()
        LogPaths = $logPaths.ToArray()
    }
}

function Get-ConversionPathsFromResultLine {
    param([AllowNull()][string]$ResultLine)
    $parsed = ConvertFrom-ResultLine -ResultLine $ResultLine
    $writePaths = Get-WritePathsFromResultFields -Fields $parsed
    [pscustomobject]@{
        Parsed = $parsed
        ReportPaths = $writePaths.ReportPaths
        LogPaths = $writePaths.LogPaths
    }
}

function Assert-SelectedConversionArtifacts {
    param(
        [Parameter(Mandatory = $true)][hashtable]$Fields,
        [Parameter(Mandatory = $true)][bool]$TeamsReport,
        [Parameter(Mandatory = $true)][bool]$EmailReport,
        [Parameter(Mandatory = $true)][bool]$CalendarReport,
        [Parameter(Mandatory = $true)][bool]$ContactsReport
    )

    $reportPaths = [System.Collections.Generic.List[string]]::new()
    $logPaths = [System.Collections.Generic.List[string]]::new()
    $selections = @(
        [pscustomobject]@{ Name = 'Teams'; Selected = $TeamsReport },
        [pscustomobject]@{ Name = 'Email'; Selected = $EmailReport },
        [pscustomobject]@{ Name = 'Calendar'; Selected = $CalendarReport },
        [pscustomobject]@{ Name = 'Contacts'; Selected = $ContactsReport }
    )
    foreach ($selection in $selections) {
        if (-not $selection.Selected) { continue }
        $outputKey = $selection.Name + 'OutputPath'
        $logKey = $selection.Name + 'LogPath'
        foreach ($artifact in @(
            [pscustomobject]@{ Key = $outputKey; Kind = 'output'; Paths = $reportPaths },
            [pscustomobject]@{ Key = $logKey; Kind = 'log'; Paths = $logPaths }
        )) {
            if (-not $Fields.ContainsKey($artifact.Key) -or
                [string]::IsNullOrWhiteSpace([string]$Fields[$artifact.Key])) {
                throw "CONVERSION_RESULT is missing selected report $($artifact.Kind) path field $($artifact.Key)."
            }
            $path = [string]$Fields[$artifact.Key]
            if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
                throw "The selected report $($artifact.Kind) file was not found for $($artifact.Key): $path"
            }
            if (-not $artifact.Paths.Contains($path)) { [void]$artifact.Paths.Add($path) }
        }
    }
    [pscustomobject]@{
        ReportPaths = $reportPaths.ToArray()
        LogPaths = $logPaths.ToArray()
    }
}

function Get-FallbackWritePaths {
    # When CONVERSION_RESULT is missing, resolve actual write targets from the display path —
    # never require the dual-mode unsuffixed DisplayPath file itself.
    param(
        [Parameter(Mandatory = $true)][string]$DisplayPath,
        [Parameter(Mandatory = $true)][bool]$TeamsReport,
        [Parameter(Mandatory = $true)][bool]$EmailReport,
        [Parameter(Mandatory = $true)][bool]$CalendarReport,
        [Parameter(Mandatory = $true)][bool]$ContactsReport
    )
    $resolved = Get-ReportOutputPaths -DisplayPath $DisplayPath -TeamsReport $TeamsReport -EmailReport $EmailReport -CalendarReport $CalendarReport -ContactsReport $ContactsReport
    @($resolved.TeamsPath, $resolved.EmailPath, $resolved.CalendarPath, $resolved.ContactsPath) |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Select-Object -Unique
}

function Get-FallbackLogPaths {
    param(
        [Parameter(Mandatory = $true)][string]$DisplayPath,
        [Parameter(Mandatory = $true)][bool]$TeamsReport,
        [Parameter(Mandatory = $true)][bool]$EmailReport,
        [Parameter(Mandatory = $true)][bool]$CalendarReport,
        [Parameter(Mandatory = $true)][bool]$ContactsReport
    )
    $resolved = Get-ReportOutputPaths -DisplayPath $DisplayPath -TeamsReport $TeamsReport -EmailReport $EmailReport -CalendarReport $CalendarReport -ContactsReport $ContactsReport
    @($resolved.TeamsPath, $resolved.EmailPath, $resolved.CalendarPath, $resolved.ContactsPath) |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Select-Object -Unique
}

function Get-GuiDiagnosticLogPaths {
    param(
        [AllowNull()][string]$ResultLine,
        [Parameter(Mandatory = $true)][string]$DisplayLogPath,
        [Parameter(Mandatory = $true)][bool]$TeamsReport,
        [Parameter(Mandatory = $true)][bool]$EmailReport,
        [Parameter(Mandatory = $true)][bool]$CalendarReport,
        [Parameter(Mandatory = $true)][bool]$ContactsReport
    )

    $resultPaths = Get-ConversionPathsFromResultLine -ResultLine $ResultLine
    if (@($resultPaths.LogPaths).Count -gt 0) {
        return @($resultPaths.LogPaths)
    }
    return @(Get-FallbackLogPaths -DisplayPath $DisplayLogPath `
        -TeamsReport $TeamsReport -EmailReport $EmailReport `
        -CalendarReport $CalendarReport -ContactsReport $ContactsReport)
}

function Get-StdoutErrorDetail {
    param(
        [AllowNull()][string]$ErrorLine,
        [AllowNull()][string[]]$LogPath
    )
    if (-not [string]::IsNullOrWhiteSpace($ErrorLine)) {
        $parsed = ConvertFrom-ResultLine -ResultLine $ErrorLine
        if ($parsed.ContainsKey('Message') -and -not [string]::IsNullOrWhiteSpace([string]$parsed['Message'])) {
            return [string]$parsed['Message']
        }
    }
    foreach ($path in @($LogPath)) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { continue }
        try {
            $recentLog = Get-Content -LiteralPath $path -Tail 80 -Encoding UTF8 -ErrorAction Stop
            $fatalLine = @($recentLog | Where-Object { $_ -match '\[ERROR\] Fatal error:' } | Select-Object -Last 1)
            if ($fatalLine -and $fatalLine[0]) { return [string]$fatalLine[0] }
        }
        catch { }
    }
    return $null
}

function Get-OutlookCleanupWarningFromLog {
    param([AllowNull()][string[]]$LogPath)
    foreach ($path in @($LogPath)) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { continue }
        try {
            $lines = Get-Content -LiteralPath $path -Tail 80 -Encoding UTF8 -ErrorAction Stop
            $match = @($lines | Where-Object { $_ -match 'PST is still attached to your Outlook profile:' } | Select-Object -Last 1)
            if ($match -and $match[0]) { return $match[0] }
        }
        catch { }
    }
    return $null
}

function Open-GeneratedReport {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [scriptblock]$LogAction
    )
    if ([IO.Path]::GetExtension($Path) -ieq '.db') {
        $viewerPath = ''
        try {
            $viewerPath = Resolve-EmailViewerPath
            if ($LogAction) { & $LogAction "Opening Email Review Viewer. Viewer: $viewerPath Database: $Path" }
            $psi = [Diagnostics.ProcessStartInfo]::new()
            $psi.FileName = $viewerPath
            $psi.UseShellExecute = $false
            $psi.Arguments = ConvertTo-NativeArgumentString -Argument @($Path)
            [void][Diagnostics.Process]::Start($psi)
        }
        catch {
            $reportedViewerPath = if ([string]::IsNullOrWhiteSpace($viewerPath)) { '(not resolved)' } else { $viewerPath }
            throw "Email Review Viewer launch failed. Viewer: $reportedViewerPath Database: $Path Error: $($_.Exception.Message)"
        }
    }
    else {
        if ($LogAction) { & $LogAction "Opening HTML report in the default browser. Report: $Path" }
        Start-Process -FilePath $Path
    }
}

function Assert-OutlookAvailableForRealRun {
    param([switch]$UseSampleData)
    if ($UseSampleData) { return }
    $outlookType = [type]::GetTypeFromProgID('Outlook.Application')
    if ($null -eq $outlookType) {
        throw 'Microsoft Outlook is required for this converter, but Outlook is not installed or is not registered on this computer. Install and configure Microsoft Outlook, then run the converter again.'
    }
}

function Start-NoGuiMode {
    try {
        if (-not $TeamsReport -and -not $EmailReport -and -not $CalendarReport -and -not $ContactsReport) {
            throw 'At least one report type must be selected (TeamsReport, EmailReport, CalendarReport, and/or ContactsReport).'
        }
        Assert-OutlookAvailableForRealRun -UseSampleData:$UseSampleData
        $result = Invoke-EmbeddedConversion -PstPath $PstPath -OutputPath $OutputPath -LogPath $LogPath -DefaultConversationParticipants $DefaultConversationParticipants -TeamsReport:$TeamsReport -EmailReport:$EmailReport -CalendarReport:$CalendarReport -ContactsReport:$ContactsReport -KeepPstAttached:$KeepPstAttached -UseSampleData:$UseSampleData
        if ($result.StdOut) { Write-Output $result.StdOut.TrimEnd() }
        # Surface child stderr without raising a terminating error, so stderr noise on a
        # successful (exit 0) run isn't turned into a failure. Success is decided strictly
        # by the child's ExitCode below.
        if ($result.StdErr) { [Console]::Error.WriteLine($result.StdErr.TrimEnd()) }
        $conversionPaths = Get-ConversionPathsFromResultLine -ResultLine $result.ResultLine
        $diagnosticLogPaths = @($conversionPaths.LogPaths)
        $outlookCleanup = Get-OutlookCleanupWarningFromLog -LogPath $diagnosticLogPaths
        if ($outlookCleanup) { Write-Warning $outlookCleanup }
        if ($result.ExitCode -ne 0) {
            $detail = Get-StdoutErrorDetail -ErrorLine $result.ErrorLine -LogPath $diagnosticLogPaths
            if ($detail) { [Console]::Error.WriteLine($detail) }
            [Environment]::Exit([int]$result.ExitCode)
        }
        # Exit 0 is necessary but not sufficient (same gate as GUI HasExited handler).
        if ([string]::IsNullOrWhiteSpace($result.ResultLine)) {
            [Console]::Error.WriteLine('Converter exited successfully but did not emit a CONVERSION_RESULT line.')
            [Environment]::Exit(1)
        }
        $fields = ConvertFrom-ResultLine -ResultLine $result.ResultLine
        $artifacts = Assert-SelectedConversionArtifacts -Fields $fields `
            -TeamsReport $TeamsReport -EmailReport $EmailReport `
            -CalendarReport $CalendarReport -ContactsReport $ContactsReport
        $script:lastReportPaths = @($artifacts.ReportPaths)
        $script:lastLogPaths = @($artifacts.LogPaths)
    }
    catch {
        [Console]::Error.WriteLine($_.Exception.Message)
        [Environment]::Exit(1)
    }
}

function Start-GuiMode {
