        $box.Size = [System.Drawing.Size]::new($w, 24)
        $form.Controls.Add($box)
        return $box
    }
    function Add-Button($text, $x, $y, $w) {
        $button = [System.Windows.Forms.Button]::new()
        $button.Text = $text
        $button.Location = [System.Drawing.Point]::new($x, $y)
        $button.Size = [System.Drawing.Size]::new($w, 28)
        $form.Controls.Add($button)
        return $button
    }

    function Get-SafeOutputBaseNameFromPstPath([string]$Path) {
        if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
        try { $baseName = [IO.Path]::GetFileNameWithoutExtension($Path.Trim('"').Trim("'")) }
        catch { $baseName = '' }
        if ([string]::IsNullOrWhiteSpace($baseName)) { return '' }
        $atIndex = $baseName.IndexOf('@')
        if ($atIndex -gt 0) { $baseName = $baseName.Substring(0, $atIndex) }
        foreach ($char in [IO.Path]::GetInvalidFileNameChars()) { $baseName = $baseName.Replace([string]$char, ' ') }
        $baseName = (($baseName -replace '\s+', ' ').Trim())
        if ([string]::IsNullOrWhiteSpace($baseName)) { return '' }
        return "$baseName Messages"
    }

    function Update-PathsForReportSelection {
        $reportPaths = Get-ReportOutputPaths -DisplayPath $outputBox.Text -TeamsReport $true -EmailReport $true -CalendarReport $true -ContactsReport $true
        $logPaths = Get-ReportOutputPaths -DisplayPath $logBox.Text -TeamsReport $true -EmailReport $true -CalendarReport $true -ContactsReport $true
        $outputBox.Text = $reportPaths.DisplayPath
        $logBox.Text = $logPaths.DisplayPath
    }

    function Move-GuiPathsIntoPstDownloadsFolder {
        if ([string]::IsNullOrWhiteSpace($pstBox.Text)) { return }
        if ([string]::IsNullOrWhiteSpace($outputBox.Text) -or [string]::IsNullOrWhiteSpace($logBox.Text)) { return }
        $outputBox.Text = Resolve-PathInPstDownloadsFolder -FilePath $outputBox.Text -PstPath $pstBox.Text -DownloadsDirectory $downloadsDir
        $logBox.Text = Resolve-PathInPstDownloadsFolder -FilePath $logBox.Text -PstPath $pstBox.Text -DownloadsDirectory $downloadsDir
        foreach ($pathToPrepare in @($outputBox.Text, $logBox.Text)) {
            $parent = Split-Path -LiteralPath $pathToPrepare
            if (-not [string]::IsNullOrWhiteSpace($parent) -and -not (Test-Path -LiteralPath $parent)) {
                [System.IO.Directory]::CreateDirectory($parent) | Out-Null
            }
        }
    }

    function Update-OutputPathsFromPstPath {
        param([bool]$Force = $false)
        if (-not $Force -and -not $script:autoNameOutputFromPst) { return }
        $baseName = Get-SafeOutputBaseNameFromPstPath -Path $pstBox.Text
        if ([string]::IsNullOrWhiteSpace($baseName)) { return }
        $outputBox.Text = Join-Path $defaultDir ($baseName + '.html')
        $logBox.Text = Join-Path $defaultDir ($baseName + '.log')
        Move-GuiPathsIntoPstDownloadsFolder
        Update-PathsForReportSelection
        $script:autoNameOutputFromPst = $true
    }

