    $openReportButton.Enabled = $false
    $openLogButton.Enabled = $false

    $progressLabel = [System.Windows.Forms.Label]::new()
    $progressLabel.Text = 'Ready'
    $progressLabel.Location = [System.Drawing.Point]::new(18, 318)
    $progressLabel.Size = [System.Drawing.Size]::new(768, 20)
    $form.Controls.Add($progressLabel)

    $progressBar = [System.Windows.Forms.ProgressBar]::new()
    $progressBar.Location = [System.Drawing.Point]::new(18, 340)
    $progressBar.Size = [System.Drawing.Size]::new(768, 18)
    $progressBar.Minimum = 0
    $progressBar.Maximum = 100
    $progressBar.Value = 0
    $progressBar.Style = 'Continuous'
    $form.Controls.Add($progressBar)

    $logText = [System.Windows.Forms.TextBox]::new()
    $logText.Location = [System.Drawing.Point]::new(18, 370)
    $logText.Size = [System.Drawing.Size]::new(768, 208)
    $logText.Multiline = $true
    $logText.ScrollBars = 'Vertical'
    $logText.ReadOnly = $true
    $logText.Font = [System.Drawing.Font]::new('Consolas', 9)
    $form.Controls.Add($logText)

    $footer = [System.Windows.Forms.Label]::new()
    $footer.Text = 'Close Outlook before running against PSTs for best results. No data is uploaded.'
    $footer.AutoSize = $true
    $footer.Location = [System.Drawing.Point]::new(18, 612)
    $form.Controls.Add($footer)

    $creditLabel = [System.Windows.Forms.Label]::new()
    $creditLabel.Text = 'By Patrick Bush'
    $creditLabel.AutoSize = $true
    $creditLabel.Font = [System.Drawing.Font]::new('Segoe UI', 8)
    $creditLabel.ForeColor = [System.Drawing.Color]::DimGray
    $creditLabel.Anchor = [System.Windows.Forms.AnchorStyles]::Bottom -bor [System.Windows.Forms.AnchorStyles]::Right
    $creditLabel.Location = [System.Drawing.Point]::new(700, 612)
    $form.Controls.Add($creditLabel)

    $script:lastReportPaths = @()
    $script:lastLogPaths = @()
    $script:lastDashboardPath = ''
    $appendLog = { param([string]$Text) $logText.AppendText($Text + [Environment]::NewLine) }
    $appendLaunchLog = {
        param([string]$Text)
        & $appendLog $Text
        foreach ($logPath in @($script:lastLogPaths)) {
            if (-not ($logPath -and (Test-Path -LiteralPath $logPath -PathType Leaf))) { continue }
            try {
                Add-Content -LiteralPath $logPath -Value ("[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Text) -Encoding UTF8
            }
            catch { }
        }
    }

    $pstBrowse.Add_Click({
        $dialog = [System.Windows.Forms.OpenFileDialog]::new()
        $dialog.Filter = 'PST files (*.pst)|*.pst|All files (*.*)|*.*'
        $dialog.Title = 'Choose Purview PST export'
        if ($dialog.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
            $pstBox.Text = $dialog.FileName
            Update-OutputPathsFromPstPath -Force $true
        }
    })
    $pstBox.Add_TextChanged({ Update-OutputPathsFromPstPath })
    $outputBrowse.Add_Click({
        $dialog = [System.Windows.Forms.SaveFileDialog]::new()
        $dialog.Filter = 'Base report path (*.html)|*.html|Email database (*.db)|*.db|All files (*.*)|*.*'
        $dialog.Title = 'Choose base output path (.html dashboard/Calendar/Contacts, .db for Teams/Email)'
        $dialog.FileName = [IO.Path]::GetFileName($outputBox.Text)
        $dialog.InitialDirectory = Split-Path -LiteralPath $outputBox.Text
        if ($dialog.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
            $outputBox.Text = $dialog.FileName
            $script:autoNameOutputFromPst = $false
        }
    })
    $logBrowse.Add_Click({
        $dialog = [System.Windows.Forms.SaveFileDialog]::new()
        $dialog.Filter = 'Log file (*.log)|*.log|Text file (*.txt)|*.txt|All files (*.*)|*.*'
        $dialog.Title = 'Choose log file path'
        $dialog.FileName = [IO.Path]::GetFileName($logBox.Text)
        $dialog.InitialDirectory = Split-Path -LiteralPath $logBox.Text
        if ($dialog.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
            $logBox.Text = $dialog.FileName
            $script:autoNameOutputFromPst = $false
        }
    })
    $openReportButton.Add_Click({
        $pathsToOpen = if ($script:lastDashboardPath -and (Test-Path -LiteralPath $script:lastDashboardPath -PathType Leaf)) {
            @($script:lastDashboardPath)
        }
        else { @($script:lastReportPaths | Select-Object -Unique) }
        foreach ($path in $pathsToOpen) {
            if (-not ($path -and (Test-Path -LiteralPath $path))) { continue }
            try {
                Open-GeneratedReport -Path $path -LogAction $appendLaunchLog
            }
            catch {
                & $appendLaunchLog $_.Exception.Message
                [System.Windows.Forms.MessageBox]::Show(
                    $form,
                    "$($_.Exception.Message)`n`nThe conversion output is still valid. Use Open Report to retry after checking the viewer files.",
                    'Could not open report',
                    'OK',
                    'Warning') | Out-Null
            }
        }
    })
    $openLogButton.Add_Click({
        foreach ($path in @($script:lastLogPaths)) {
            if (-not ($path -and (Test-Path -LiteralPath $path))) { continue }
            try { Start-Process -FilePath $path } catch { }
        }
    })

    function Set-ConversionProgress([int]$Value, [string]$Status) {
        $progressBar.Style = 'Continuous'
        $boundedValue = [Math]::Max($progressBar.Minimum, [Math]::Min($progressBar.Maximum, $Value))
        if ($boundedValue -lt $script:lastProgressValue) { $boundedValue = $script:lastProgressValue }
        $script:lastProgressValue = $boundedValue
        $progressBar.Value = $boundedValue
        $progressLabel.Text = $Status
        $progressBar.Update()
        $progressLabel.Update()
    }

    function Reset-ConversionProgress([string]$Status) {
        $script:lastProgressValue = 0
        $progressBar.Style = 'Continuous'
        $progressBar.Value = 0
        $progressLabel.Text = $Status
        $progressBar.Update()
        $progressLabel.Update()
    }

    function Set-ConversionControlsEnabled([bool]$Enabled) {
        $convertButton.Enabled = $Enabled
        $pstBrowse.Enabled = $Enabled
        $outputBrowse.Enabled = $Enabled
        $logBrowse.Enabled = $Enabled
        $keepCheck.Enabled = $Enabled
        $pstBox.Enabled = $Enabled
        $outputBox.Enabled = $Enabled
        $logBox.Enabled = $Enabled
    }

    function Complete-ConversionTeardown {
        # Shared, idempotent teardown for every stop path (completion, cancel, FormClosing,
        # start failure): optionally tree-kill the child, stop the stdout reader, remove the
        # temp dir, and clear active-run state. Callers manage their own UI control state.
        param([switch]$KillProcess)
        $conversion = $script:activeConversion
        if ($null -ne $conversion) {
            if ($KillProcess) { try { Stop-ProcessTree -Process $conversion.Process } catch { } }
            Stop-ConversionOutputReader -Conversion $conversion
            if (($conversion.PSObject.Properties.Name -contains 'TempDir') -and $conversion.TempDir -and (Test-Path -LiteralPath $conversion.TempDir)) {
                Remove-Item -LiteralPath $conversion.TempDir -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $script:activeConversion = $null
        $script:activeRunId = $null
    }

    function Assert-GuiOutputPathsValid {
        if ([string]::IsNullOrWhiteSpace($outputBox.Text)) { throw 'Choose a base output path.' }
        if ([string]::IsNullOrWhiteSpace($logBox.Text)) { throw 'Choose a log file path.' }
        try { $outputFullPath = [IO.Path]::GetFullPath($outputBox.Text) }
        catch { throw "Base output path is not valid. $($_.Exception.Message)" }
        try { $logFullPath = [IO.Path]::GetFullPath($logBox.Text) }
        catch { throw "Log file path is not valid. $($_.Exception.Message)" }
        if ($outputFullPath -ieq $logFullPath) { throw 'Output and Log file must be different files.' }
        if ([IO.Path]::GetExtension($outputFullPath) -notin @('.html','.htm','.db')) { throw 'Base output must end in .html, .htm, or .db.' }
        if ([IO.Path]::GetExtension($logFullPath) -notin @('.log','.txt')) { throw 'Log file must end in .log or .txt.' }
        foreach ($check in @(@{ Label = 'Output'; Path = $outputFullPath }, @{ Label = 'Log'; Path = $logFullPath })) {
            $pathToCheck = $check.Path
            if (Test-Path -LiteralPath $pathToCheck -PathType Container) { throw "Path points to a folder, not a file: $pathToCheck" }
            $parent = Split-Path -LiteralPath $pathToCheck
            if ([string]::IsNullOrWhiteSpace($parent)) { throw "Path must include a parent folder: $pathToCheck" }
            if (Test-Path -LiteralPath $parent -PathType Leaf) { throw "Parent path is a file, not a folder: $parent" }
            if (-not (Test-Path -LiteralPath $parent -PathType Container)) { throw "$($check.Label) folder does not exist: $parent" }
        }
    }

    $script:activeConversion = $null
    $script:conversionStartedAt = $null
    $script:lastProgressValue = 0
    $script:activeRunId = $null
    $script:capturedResultLine = $null
    $script:capturedErrorLine = $null
    $script:sawStdoutProgress = $false
    $script:lastStatusBase = 'Reading PST...'

    $progressTimer = [System.Windows.Forms.Timer]::new()
    $progressTimer.Interval = 1000
    $progressTimer.Add_Tick({
        if (-not $script:activeConversion) { return }

        $proc = $script:activeConversion.Process
        $elapsedSeconds = [Math]::Max(1, [int]((Get-Date) - $script:conversionStartedAt).TotalSeconds)
        $elapsedText = [TimeSpan]::FromSeconds($elapsedSeconds).ToString('hh\:mm\:ss')

        # Progress is driven entirely by the run-ID-tagged stdout the core emits. Draining the
        # thread-safe queue here (on the UI thread) and gating each line by $script:activeRunId
        # makes the bar structurally immune to stale logs and core prose changes. The log file is
        # no longer parsed for progress - only for fatal-error detail on a nonzero exit below.
        # Capture RESULT/ERROR during every drain so the progress pass cannot discard them before
        # HasExited handling (that race previously fell back to dual-mode DisplayPath).
        $latest = $null
        $queue = $script:activeConversion.OutputQueue
        if ($queue) {
            $item = $null
            while ($queue.TryDequeue([ref]$item)) {
                if ($item -like 'CONVERSION_ERROR|*') { $script:capturedErrorLine = $item }
                if ($item -like 'CONVERSION_RESULT|*') { $script:capturedResultLine = $item }
                $parsed = ConvertFrom-ProgressStdoutLine -Line $item -ExpectedRunId $script:activeRunId
                if ($null -ne $parsed) { $latest = $parsed }
            }
        }

        if ($null -ne $latest) {
            $script:sawStdoutProgress = $true
            $script:lastStatusBase = $latest.Status
            Set-ConversionProgress $latest.Percent ("{0}; elapsed {1}" -f $latest.Status, $elapsedText)
        }
        elseif ($script:sawStdoutProgress) {
            # No new applicable line this tick: hold the bar, just refresh the elapsed time.
            Set-ConversionProgress $script:lastProgressValue ("{0}; elapsed {1}" -f $script:lastStatusBase, $elapsedText)
        }
        else {
            # No run-ID-verified stdout has arrived yet: time-based fallback pulse (10-30).
            $pulse = [Math]::Min(30, 10 + [int][Math]::Floor($elapsedSeconds / 30))
            Set-ConversionProgress $pulse ("Reading PST... elapsed {0}" -f $elapsedText)
        }

        if ($proc.HasExited) {
            $progressTimer.Stop()
            # Drain any stdout lines still in flight when the child exits (race between
            # async reader and the final CONVERSION_RESULT / CONVERSION_ERROR line).
            if ($queue) {
                $item = $null
                while ($queue.TryDequeue([ref]$item)) {
                    if ($item -like 'CONVERSION_ERROR|*') { $script:capturedErrorLine = $item }
                    if ($item -like 'CONVERSION_RESULT|*') { $script:capturedResultLine = $item }
                    $parsed = ConvertFrom-ProgressStdoutLine -Line $item -ExpectedRunId $script:activeRunId
                    if ($null -ne $parsed) { $latest = $parsed }
                }
            }
            try {
                if ($proc.ExitCode -ne 0) {
                    $detail = ''
                    $diagnosticLogPaths = @(Get-GuiDiagnosticLogPaths `
                        -ResultLine $script:capturedResultLine `
                        -DisplayLogPath $script:activeConversion.LogPath `
                        -TeamsReport $script:activeConversion.TeamsReport `
                        -EmailReport $script:activeConversion.EmailReport `
                        -CalendarReport $script:activeConversion.CalendarReport `
                        -ContactsReport $script:activeConversion.ContactsReport)
                    $stdoutError = Get-StdoutErrorDetail -ErrorLine $script:capturedErrorLine -LogPath $diagnosticLogPaths
                    if ($stdoutError) { $detail = "`n`n$stdoutError" }
                    throw "Converter exited with code $($proc.ExitCode). See the log file for details.$detail"
                }
                if ([string]::IsNullOrWhiteSpace($script:capturedResultLine)) {
                    throw 'Converter exited successfully but did not emit a CONVERSION_RESULT line.'
                }
                $fields = ConvertFrom-ResultLine -ResultLine $script:capturedResultLine
                $artifacts = Assert-SelectedConversionArtifacts -Fields $fields `
                    -TeamsReport $script:activeConversion.TeamsReport `
                    -EmailReport $script:activeConversion.EmailReport `
                    -CalendarReport $script:activeConversion.CalendarReport `
                    -ContactsReport $script:activeConversion.ContactsReport
                $script:lastReportPaths = @($artifacts.ReportPaths)
                $script:lastLogPaths = @($artifacts.LogPaths)
                $script:lastDashboardPath = Get-DashboardLaunchPath -Fields $fields -DisplayPath $script:activeConversion.OutputPath
                $openReportButton.Enabled = $script:lastReportPaths.Count -gt 0
                $openLogButton.Enabled = @($script:lastLogPaths | Where-Object { Test-Path -LiteralPath $_ }).Count -gt 0

                Set-ConversionProgress 100 'Conversion completed successfully. Opening dashboard...'
                & $appendLog 'Conversion completed successfully.'
                $launchWarnings = [System.Collections.Generic.List[string]]::new()
                try {
                    if (-not (Test-Path -LiteralPath $script:lastDashboardPath -PathType Leaf)) {
                        throw "Dashboard file was not found: $script:lastDashboardPath"
                    }
                    Open-GeneratedReport -Path $script:lastDashboardPath -LogAction $appendLaunchLog
                    & $appendLaunchLog "Opened dashboard: $script:lastDashboardPath"
                }
                catch {
                    $warning = "Could not open the dashboard automatically: $($_.Exception.Message)"
                    $launchWarnings.Add($warning)
                    & $appendLaunchLog $warning
                }
                $outlookCleanup = Get-OutlookCleanupWarningFromLog -LogPath $script:lastLogPaths
                if ($outlookCleanup) {
                    & $appendLog $outlookCleanup
                    $outlookNote = "`n`nOutlook cleanup warning:`n$outlookCleanup"
                }
                else { $outlookNote = '' }
                if ($launchWarnings.Count -eq 0) {
                    [System.Windows.Forms.MessageBox]::Show($form, "Conversion completed successfully.`n`nDashboard:`n$script:lastDashboardPath`n`nThe dashboard opened in your browser and links to every report:`n$($script:lastReportPaths -join "`n")$outlookNote", 'Conversion complete', 'OK', 'Information') | Out-Null
                }
                else {
                    [System.Windows.Forms.MessageBox]::Show($form, "Conversion completed successfully, but the dashboard could not be opened automatically.`n`nDashboard:`n$script:lastDashboardPath`n`nReports:`n$($script:lastReportPaths -join "`n")`n`n$($launchWarnings -join "`n")`n`nUse Open Report to retry. The conversion output is valid.$outlookNote", 'Conversion complete — open warning', 'OK', 'Warning') | Out-Null
                }
            }
            catch {
                $progressBar.Style = 'Continuous'
                $progressBar.Value = 0
                $progressLabel.Text = 'Conversion failed.'
                & $appendLog ('FAILED: ' + $_.Exception.Message)
                [System.Windows.Forms.MessageBox]::Show($form, $_.Exception.Message, 'Conversion failed', 'OK', 'Error') | Out-Null
            }
            finally {
                Complete-ConversionTeardown
                Set-ConversionControlsEnabled $true
                $cancelButton.Enabled = $false
            }
        }
    })

    $form.Add_FormClosing({
        if (-not $script:activeConversion) { return }
        $answer = [System.Windows.Forms.MessageBox]::Show($form, 'A conversion is still running. Closing the app will stop the conversion process. Close and stop conversion?', 'Conversion still running', 'YesNo', 'Warning')
        if ($answer -ne [System.Windows.Forms.DialogResult]::Yes) {
            $_.Cancel = $true
            return
        }
        $progressTimer.Stop()
        Complete-ConversionTeardown -KillProcess
    })

    $convertButton.Add_Click({
        try {
            $logText.Clear()
            $script:sawStdoutProgress = $false
            $script:lastStatusBase = 'Reading PST...'
            Reset-ConversionProgress 'Ready'
            & $appendLog 'Starting conversion...'
            Set-ConversionProgress 5 'Starting conversion...'
            Set-ConversionControlsEnabled $false
            $openReportButton.Enabled = $false
            $openLogButton.Enabled = $false

            if (-not (Test-Path -LiteralPath $pstBox.Text -PathType Leaf)) { throw 'Choose an existing PST file.' }
            if ([IO.Path]::GetExtension($pstBox.Text) -ine '.pst') { throw "Selected file is not a .pst: $([IO.Path]::GetFileName($pstBox.Text))" }
            Update-OutputPathsFromPstPath
            Move-GuiPathsIntoPstDownloadsFolder
            Assert-GuiOutputPathsValid

            $reportOutputPaths = Get-ReportOutputPaths -DisplayPath $outputBox.Text -TeamsReport $true -EmailReport $true -CalendarReport $true -ContactsReport $true
            $logOutputPaths = Get-ReportOutputPaths -DisplayPath $logBox.Text -TeamsReport $true -EmailReport $true -CalendarReport $true -ContactsReport $true
            $targetReportPaths = @($reportOutputPaths.TeamsPath, $reportOutputPaths.EmailPath, $reportOutputPaths.CalendarPath, $reportOutputPaths.ContactsPath, (Get-DashboardOutputPath -DisplayPath $outputBox.Text)) |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
            $targetLogPaths = @($logOutputPaths.TeamsPath, $logOutputPaths.EmailPath, $logOutputPaths.CalendarPath, $logOutputPaths.ContactsPath) |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
            foreach ($typedPath in @($targetReportPaths) + @($targetLogPaths)) {
                if (Test-Path -LiteralPath $typedPath -PathType Container) {
                    throw "Selected output path points to a folder, not a file: $typedPath"
                }
                $typedParent = Split-Path -LiteralPath $typedPath
                if (-not (Test-Path -LiteralPath $typedParent -PathType Container)) {
                    throw "Selected output folder does not exist: $typedParent"
                }
            }
            $existingWritePaths = @(@($targetReportPaths) + @($targetLogPaths) |
                Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } |
                Select-Object -Unique)
            if ($existingWritePaths.Count -gt 0) {
                $overwriteAnswer = [System.Windows.Forms.MessageBox]::Show($form, "The following selected report/log file(s) already exist and will be overwritten:`n$($existingWritePaths -join "`n")`n`nContinue?", 'Overwrite existing files?', 'YesNo', 'Warning')
                if ($overwriteAnswer -ne [System.Windows.Forms.DialogResult]::Yes) {
                    & $appendLog 'Canceled: existing selected report/log file(s) not overwritten.'
                    Reset-ConversionProgress 'Canceled.'
                    Complete-ConversionTeardown
                    Set-ConversionControlsEnabled $true
                    $cancelButton.Enabled = $false
                    return
                }
            }

            Set-ConversionProgress 10 'Checking required programs...'
            [void](Resolve-PowerShell7Path)
            Assert-OutlookAvailableForRealRun -UseSampleData:$false
            [void](Resolve-EmailViewerPath)

            Set-ConversionProgress 12 'Starting PST read...'
            $script:conversionStartedAt = Get-Date
            $script:activeRunId = [guid]::NewGuid().ToString('N')
            $script:capturedResultLine = $null
            $script:capturedErrorLine = $null
            $script:activeConversion = Start-EmbeddedConversionProcess -PstPath $pstBox.Text -OutputPath $outputBox.Text -LogPath $logBox.Text -DefaultConversationParticipants @() -TeamsReport:$true -EmailReport:$true -CalendarReport:$true -ContactsReport:$true -KeepPstAttached:($keepCheck.Checked) -UseSampleData:$false -RunId $script:activeRunId
            # Snapshot the normalized paths so mid-run edits to the (now-disabled) textboxes can't
            # redirect the active-run fatal-detail read, completion report, or opened log.
            $script:activeConversion | Add-Member -NotePropertyName PstPath -NotePropertyValue ([IO.Path]::GetFullPath($pstBox.Text))
            $script:activeConversion | Add-Member -NotePropertyName OutputPath -NotePropertyValue ([IO.Path]::GetFullPath($outputBox.Text))
            $script:activeConversion | Add-Member -NotePropertyName LogPath -NotePropertyValue ([IO.Path]::GetFullPath($logBox.Text))
            $script:activeConversion | Add-Member -NotePropertyName TeamsReport -NotePropertyValue $true
            $script:activeConversion | Add-Member -NotePropertyName EmailReport -NotePropertyValue $true
            $script:activeConversion | Add-Member -NotePropertyName CalendarReport -NotePropertyValue $true
            $script:activeConversion | Add-Member -NotePropertyName ContactsReport -NotePropertyValue $true
            $cancelButton.Enabled = $true
            $progressTimer.Start()
        }
        catch {
            $progressTimer.Stop()
            $progressBar.Style = 'Continuous'
            $progressBar.Value = 0
            $progressLabel.Text = 'Conversion failed.'
            & $appendLog ('FAILED: ' + $_.Exception.Message)
            [System.Windows.Forms.MessageBox]::Show($form, $_.Exception.Message, 'Conversion failed', 'OK', 'Error') | Out-Null
            Complete-ConversionTeardown -KillProcess
            Set-ConversionControlsEnabled $true
            $cancelButton.Enabled = $false
        }
    })

    $cancelButton.Add_Click({
        if (-not $script:activeConversion) { return }
        $progressTimer.Stop()
        Complete-ConversionTeardown -KillProcess
        Set-ConversionControlsEnabled $true
        $cancelButton.Enabled = $false
        $progressBar.Style = 'Continuous'
        $progressBar.Value = 0
        $script:lastProgressValue = 0
        $progressLabel.Text = 'Conversion canceled.'
        & $appendLog 'Conversion canceled.'
    })

    [void]$form.ShowDialog()
}

if ($NoGui) { Start-NoGuiMode } else { Start-GuiMode }
